-- Deepening Journey Contents (Part 2)
-- Aprofundando a Jornada de Clareza Mental (c3c3c3c3-3030-4000-8000-000000000003)
UPDATE journey_steps SET content = jsonb_build_object(
  'pch', 'Deus não grita; Ele sussurra no "murmúrio de uma brisa suave". Se você não consegue ouvi-Lo, talvez não seja porque Ele está em silêncio, mas porque o seu ruído interno é ensurdecedor.',
  'verse', '1Rs 19,12',
  'lectio', 'Leia 1 Reis 19,9-13. Elias não encontrou Deus no furacão, nem no terremoto, nem no fogo. Ele O encontrou no silêncio que se seguiu. Onde você O tem buscado?',
  'practice', 'Faça um "jejum de ruído" por 30 minutos hoje. Desligue músicas, podcasts e notificações. Sente-se em silêncio e observe como sua mente luta para fugir do agora. Não lute contra os pensamentos, apenas deixe-os passar como nuvens.',
  'question', 'Qual é o pensamento "barulhento" que você usa para evitar ouvir a voz mansa da sua consciência?',
  'reflection', 'O ruído é o anestésico da alma moderna. Sem silêncio, não há autoconhecimento; sem autoconhecimento, não há conversão real.'
) WHERE id = '2711a145-076a-4092-99b4-9a1f1992ae2b';

UPDATE journey_steps SET content = jsonb_build_object(
  'pch', 'A ansiedade é o pecado de tentar viver no amanhã com a graça que Deus só nos deu para o hoje. Quando sobrecarregamos a mente com cenários hipotéticos, estamos recusando o "pão nosso de cada dia".',
  'verse', 'Sl 131,1-2',
  'lectio', 'Leia o Salmo 131. É a oração de quem desistiu de entender tudo para poder confiar em Tudo. "Não ando à procura de grandezas, nem de coisas superiores a mim".',
  'practice', 'Identifique um compromisso ou uma preocupação que "não é sua" hoje. Entregue-a explicitamente a Deus: "Senhor, isto é Teu, não meu". Sinta o peso físico saindo dos seus ombros.',
  'question', 'O que na sua vida é "superior a você" e que você insiste em tentar controlar sozinho?',
  'reflection', 'A clareza mental nasce da humildade de aceitar que somos criaturas, não o Criador. Menos controle é mais paz.'
) WHERE id = '61ed9a2c-de4a-446e-bda9-c8902adbe470';

-- Aprofundando a Jornada de Aprofundamento Místico (a1b2c3d4-0003-4000-8000-000000000003)
UPDATE journey_steps SET content = jsonb_build_object(
  'intro', 'A mística não é para os iluminados, mas para os sedentos. São João da Cruz ensina que para chegar ao "Tudo", devemos passar pelo "Nada" dos sentidos. O chamado à contemplação é o convite para deixar de olhar para as mãos de Deus e começar a olhar para a Sua Face.',
  'text', 'A alma que deseja alcançar a perfeição deve primeiro passar pela noite escura dos sentidos, onde o consolo humano seca para que a fonte divina possa jorrar.',
  'source', 'São João da Cruz',
  'prayer', 'Ó Noite que me guiaste, ó noite amável mais do que a alvorada! Uni-me ao meu Amado de tal forma que minha vida seja apenas um reflexo dEle.',
  'practice', 'Passe 15 minutos em adoração silenciosa (mesmo que seja diante de um crucifixo em casa). Não peça nada. Apenas "gaste" seu tempo aos pés dEle, como Maria de Betânia.',
  'reflection', 'A contemplação é um olhar de amor fixo em Jesus. É o silêncio que comunica mais que mil palavras.'
) WHERE id = 'bfd8ee6c-4069-42a9-85ec-f5558311d60f';

UPDATE journey_steps SET content = jsonb_build_object(
  'instruction', 'A oração de quietude é o repouso da alma em Deus. Não se trata de esvaziar a mente como nas técnicas orientais, mas de preenchê-la com a Presença de Alguém que te ama.',
  'step_by_step', '1) Sente-se confortavelmente, mas alerta. 2) Feche os olhos e respire a paz de Cristo. 3) Escolha uma palavra sagrada (ex: Jesus, Abba, Maranatha). 4) Sempre que um pensamento te levar embora, volte suavemente à palavra. 5) Permaneça assim por 20 minutos.',
  'reflection', 'O fruto da quietude não se sente durante a oração, mas depois dela: uma paciência nova, um olhar mais doce, um coração mais centrado.',
  'practice', 'Não julgue a qualidade da sua oração pelo número de distrações, mas pela sua vontade de voltar a Deus cada vez que se distraiu.'
) WHERE id = '7022626f-dd2e-4568-91b1-4eeccfc1b688';

-- Aprofundando a Jornada de Prisão Interior (a1b2c3d4-0004-4000-8000-000000000004)
UPDATE journey_steps SET content = jsonb_build_object(
  'intro', 'Toda libertação começa com um ato de coragem radical: a honestidade total. O pecado e o trauma sobrevivem na sombra; eles morrem quando são trazidos à luz da Presença de Deus. Reconhecer que você está preso é o primeiro milagre da liberdade.',
  'prayer', 'Senhor, arranca as máscaras que eu mesmo criei para sobreviver. Eu não quero mais a segurança da minha cela; eu quero a incerteza da Tua liberdade. Sonda-me e conhece-me.',
  'practice', 'Escreva em um papel: "Eu não sou livre na área de [X]". Olhe para essa frase. Sinta o peso dela. Depois, escreva embaixo: "Mas o Senhor é soberano sobre [X]". Amanhã, vamos agir sobre isso.',
  'scripture', '"Conhecereis a verdade, e a verdade vos libertará." — Jo 8,32. A verdade aqui não é um conceito, é uma Pessoa.',
  'reflection', 'A negação é o carcereiro mais eficiente. Qual é a mentira que você conta a si mesmo para não ter que enfrentar o trabalho da mudança?',
  'journal_prompt', 'Se Jesus abrisse hoje todas as portas da sua alma, qual cômodo você teria vergonha de mostrar? Por que você acha que Ele, que morreu por você, não suportaria olhar para lá?'
) WHERE id = 'b1b2c3d4-0001-4000-8000-000000000001';

UPDATE journey_steps SET content = jsonb_build_object(
  'intro', 'As correntes mais fortes não são feitas de ferro, mas de vergonha e narrativas distorcidas. O inimigo da nossa alma trabalha na base do "sempre" e do "nunca": "você sempre será assim", "você nunca será livre". Essas são as grades da sua prisão mental.',
  'prayer', 'Espírito Santo, sopra sobre as cinzas da minha esperança. Quebra os decretos de condenação que eu assinei contra mim mesmo. Eu sou filho, não escravo.',
  'practice', 'Identifique uma frase de autocrítica que você repete constantemente (ex: "Eu sou um fracasso"). Substitua-a hoje por uma afirmação de identidade filial (ex: "Eu sou amado por Deus apesar das minhas falhas"). Repita isso toda vez que a corrente apertar.',
  'scripture', '"Onde está o Espírito do Senhor, aí há liberdade." — 2Cor 3,17',
  'reflection', 'A liberdade não é a ausência de luta, mas a presença de um propósito maior que a dor. Pelo que vale a pena lutar pela sua liberdade?',
  'journal_prompt', 'Quais são as narrativas de "sempre" e "nunca" que governam seu humor hoje? De onde elas vieram?'
) WHERE id = 'b1b2c3d4-0002-4000-8000-000000000002';
